			            SUM(FATOS_PARTICULAR_TVD_IVD[TVD_SIMPLIFICADO])
			        )
			    ),

			    ALL(AP_CONVERSAO),

			    FILTER(
			        DIM_LOCAL,
			        NOT DIM_LOCAL[TIPO_LOCAL]
			            IN {"DEPÓSITO", "CD", "LOJA VIRTUAL"}
			    ),

			    FILTER(
			        DIM_CATALOGO_LOCAL,
			        NOT DIM_CATALOGO_LOCAL[Tipo local]
			            IN {"DEPÓSITO", "CD", "LOJA VIRTUAL"}
			    )
			)
